const r=await rpc('rs_beta_checkout_reserve',{p_user:id,p_plan:b.plan});const price=await stripe('prices/'+encodeURIComponent(r.price));if(!price.active||price.currency!=='usd'||r.amount!==499||r.interval!=='month'||price.unit_amount!==r.amount||price.recurring?.interval!==r.interval||price.recurring?.interval_count!==1)throw Error('UNKNOWN_PRICE');
let customer=r.customer;if(!customer){const x=await stripe('customers',{'metadata[roadshop_user]':id},'rs-customer-'+id);customer=x.id;if(typeof customer!=='string'||!customer.startsWith('cus_'))throw Error('STRIPE_ERROR');const saved=await db('rs_subscriptions?user_id=eq.'+id+'&customer_id=is.null','PATCH',{customer_id:customer});if(!saved.length){const actual=await sub(id);if(actual?.customer_id!==customer)throw Error('MANUAL_REVIEW')}}
// Stripe requires at least 30 minutes until expiry for a new session.
